sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    // Populate Location reference field based
    // on location from source file, or set
    // skip to true if no reference can be found.

    // User-supplied mapping of location codes 
    // to location names, filtered down to only
    // entries where both key and value 
    // are populated.
    // The location-name may be a partial name.
    //
    // [{
    //    "key": "AURORA",
    //    "value": "808 N Route 59, Aurora,IL"
    //  }, ...]
    var locations = new BaseDataSourceReader(gs.getCurrentScopeName(), "Locations")
        .getData()
        .filter(e => e.key && e.value);

    // The resolver returns an object describing whether
    // that location-name (@value, above) maps to:
	// a Location reference (valid),
	// or to nothing (invalid),
	// or to multiple references (also invalid).
    var resolver = new LocationResolver();

    // Loop through the rows, passing each u_location to 
    // the resolver. If the resolver returns a good reference 
    // to a Model, populate that reference into the row, otherwise
    // mark the row skipped.
    var gr_is_row = new GlideRecord(source.getTableName());
    gr_is_row.addQuery("sys_import_set", import_set.sys_id);
    gr_is_row.addQuery("u_skip", false);
    gr_is_row.query();
    while (gr_is_row.hasNext()) {
        gr_is_row.next();

		// location in the source is actually a code, like "621-6A".
        var location_code = gr_is_row.getValue("u_location")||"";

		// The value the user mapped that code to is in 'locations' above.
		// That's just the content of the Locations spreadhseet, as 
		// an array of objects. The resolver figures out if that 
		// user-supplied value can be mapped to a Location reference.

		// TODO
        // We already checked, in a previous script, that
        // each location code in the source file is listed 
		// in the location code/Location name map, so we
        // can skip checking that here

        var locationName = locations[location_code];
        var response = resolver.resolve(locationName, false);
        if (response.valid) {
            gr_is_row.setValue("u_location_ref", response.refs[0].sys_id);
            gr_is_row.update();
        } else {
            gr_is_row.setValue("u_skip", true);
            gr_is_row.setValue("u_skip_reason", response.message);
            gr_is_row.update();
        }

    }

})(source, map, log, target);
